begin;
set local test.kakao_clock='2026-11-16 00:15+00'; -- KST09:15, base08:00 published
insert into public.kakao_weather_regions(region_key,label,nx,ny,enabled,verified_at) values('cache-a','Region A',60,127,true,now()),('cache-b','Region B',60,127,true,now());
update public.kakao_weather_regions set forecast_code='1100000000' where region_key in ('cache-a','cache-b');
do $$declare a jsonb;b jsonb;f jsonb;token uuid;begin
 a:=public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','0800');
 if a->>'status'<>'unavailable' or exists(select 1 from public.kakao_weather_usage) then raise exception 'Default budget not off';end if;
 update public.kakao_weather_controls set daily_attempt_budget=1;
 a:=public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','0800');token:=(a->>'lease_token')::uuid;
 if a->>'status'<>'fetch' then raise exception 'No lease';end if;
 b:=public.kakao_service_weather_claim('cache-b','2026-11-16','20261116','0800');
 if b->>'status'<>'wait' then raise exception 'Shared grid duplicated';end if;
 f:='{"status":"ok","day":"2026-11-16","low":3,"high":12,"morning":"맑음","afternoon":"흐림","issued_day":"2026-11-16","issued_time":"08:00"}';
 if public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','0800',gen_random_uuid(),f) then raise exception 'Wrong lease accepted';end if;
 if not public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','0800',token,f) then raise exception 'Complete failed';end if;
 b:=public.kakao_service_weather_claim('cache-b','2026-11-16','20261116','0800');
 if b->>'status'<>'cached' or b->>'region_name'<>'Region B' then raise exception 'Shared label/cache failure';end if;
 if (select attempts from public.kakao_weather_usage)<>1 then raise exception 'Cache consumed budget';end if;
 perform set_config('test.kakao_clock','2026-11-16 02:15+00',true);
 a:=public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','1100');
 if a->>'status'<>'unavailable' then raise exception 'Budget exceeded';end if;
 update public.kakao_weather_controls set daily_attempt_budget=10;
 a:=public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','1100');
 if public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','1100',(a->>'lease_token')::uuid,'{"secret":"must not persist"}') then raise exception 'Invalid forecast returned success';end if;
 if exists(select 1 from public.kakao_weather_cache where forecast::text like '%secret%') then raise exception 'Unsafe JSON persisted';end if;
 if public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','1100')->>'status'<>'wait' then raise exception 'Failure TTL missing';end if;
 if private.kakao_weather_request_valid('2026-11-16','20261116','0800') or private.kakao_weather_request_valid('2026-11-15','20261115','2300') then raise exception 'Invalid timing allowed';end if;
 perform set_config('test.kakao_clock','2026-11-16 02:21+00',true);
 a:=public.kakao_service_weather_claim('cache-a','2026-11-16','20261116','1100');
 f:=jsonb_set(jsonb_set(jsonb_set(f,'{issued_time}','"08:00"'),'{low}','20'),'{high}','10');
 if public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','1100',(a->>'lease_token')::uuid,f) then raise exception 'Inverted temperatures accepted';end if;
 if exists(select 1 from public.kakao_weather_cache where base_time='1100' and forecast is not null) then raise exception 'Invalid temperature cache usable';end if;
 token:=gen_random_uuid();
 update public.kakao_weather_cache set lease_token=token,lease_until=private.kakao_test_clock()+interval '30 seconds' where base_time='1100';
 f:=jsonb_set(jsonb_set(jsonb_set(f,'{low}','3'),'{high}','12'),'{morning}','"<script>"');
 if public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','1100',token,f) then raise exception 'HTML accepted';end if;
 token:=gen_random_uuid();update public.kakao_weather_cache set lease_token=token,lease_until=private.kakao_test_clock()+interval '30 seconds' where base_time='1100';
 f:=jsonb_set(jsonb_set(f,'{morning}','"맑음"'),'{issued_day}','"2026-11-14"');
 if public.kakao_service_weather_complete('cache-a','2026-11-16','20261116','1100',token,f) then raise exception 'Stale publication accepted';end if;
 if has_function_privilege('authenticated','public.kakao_service_weather_claim(text,date,text,text)','execute') or has_table_privilege('anon','public.kakao_weather_cache','select') then raise exception 'ACL leak';end if;
end $$;
select 'Shared grid, current label, lease CAS, budget OFF/cap, JSON sanitize, failure TTL, time bounds and ACL passed' as result;
rollback;
